FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 039: curved sheets other than cylinders extended: cones, spheres, extruded splines. Generated by tools/fixtures/gen-batch-039.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Each face of a sheet: its area, its surface's type, and for a B-spline its degrees, knots and poles.
function sheetProbe(context is Context, sheet is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(sheet, EntityType.FACE)))
    {
        const s = evSurfaceDefinition(context, { "face" : face });
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6), "type" : s.surfaceType };
        if (s is BSplineSurface)
        {
            var rows = [];
            for (var row in s.controlPoints)
                rows = append(rows, mapArray(row, round6));
            entry.bspline = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational,
                              "uKnots" : mapArray(s.uKnots, function(k) { return roundToPrecision(k, 9); }),
                              "vKnots" : mapArray(s.vKnots, function(k) { return roundToPrecision(k, 9); }), "poles" : rows };
        }
        out = append(out, entry);
    }
    return out;
}

// extend-surface: a quarter of a cone extended 5 mm round it, at its edge in the xz plane
export function c001(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(profile, "line1", { "start" : vector(10, 0) * millimeter, "end" : vector(5, 20) * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "profile", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : false, "endBound" : RevolveBoundingType.BLIND, "oppositeDirection" : false, "angle" : 90 * degree });
    extendSurface(context, id + "extend1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(7.5, 0, 10) * millimeter), "endCondition" : ExtendBoundingType.BLIND, "extendDistance" : 5 * millimeter, "oppositeDirection" : false, "maintainCurvature" : false, "tangentPropagation" : false });
    return { "faces" : sheetProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SHEET)) };
}

